/*! `cpp` grammar compiled for Highlight.js - Arduino variant */
(() => {
  var e = (() => {
    "use strict";
    return e => {
      const n = e.regex,
        a = /[\p{XID_Start}_]\p{XID_Continue}*/u,
        i = [
          "and", "or", "not", "bitand", "bitor", "xor", "compl", "and_eq", "or_eq",
          "not_eq", "xor_eq", "asm", "auto", "bool", "break", "case", "catch", "char",
          "class", "const", "consteval", "const_cast", "continue", "co_await", "co_return",
          "co_yield", "decltype", "default", "delete", "do", "double", "else", "enum",
          "explicit", "export", "extern", "false", "float", "for", "friend", "goto", "if",
          "inline", "int", "long", "mutable", "namespace", "new", "noexcept", "nullptr",
          "operator", "private", "protected", "public", "register", "reinterpret_cast",
          "requires", "return", "short", "signed", "sizeof", "static", "static_assert",
          "static_cast", "struct", "switch", "template", "this", "throw", "true", "try",
          "typedef", "typeid", "typename", "union", "unsigned", "using", "virtual", "void",
          "volatile", "wchar_t", "while"
        ],
        s = {
          $pattern: /[a-zA-Z_][a-zA-Z0-9_]*/,
          keyword: i,
          built_in: [
            // Arduino 核心函式
            "setup", "loop", "pinMode", "digitalWrite", "digitalRead",
            "analogWrite", "analogRead",
            // 序列埠
            "Serial", "Serial1", "Serial2", "Serial3", "SerialUSB",
            // 數學
            "constrain", "map", "min", "max", "pow", "sqrt", "abs",
            "sin", "cos", "tan", "random", "randomSeed",
            // 字串
            "String", "strlen", "strcmp", "strcpy", "strcat", "strstr",
            "atoi", "atol", "atof", "dtostrf", "sprintf", "snprintf",
            // 中斷
            "attachInterrupt", "detachInterrupt", "interrupts", "noInterrupts",
            // 時間
            "delay", "delayMicroseconds", "millis", "micros",
            // I/O
            "tone", "noTone", "shiftOut", "shiftIn", "pulseIn", "pulseInLong",
            // 常數
            "HIGH", "LOW", "INPUT", "OUTPUT", "INPUT_PULLUP",
            "LED_BUILTIN", "LED_BUILTIN_RX", "LED_BUILTIN_TX",
            "A0", "A1", "A2", "A3", "A4", "A5", "A6", "A7",
            "A8", "A9", "A10", "A11", "A12", "A13", "A14", "A15",
            "CHANGE", "RISING", "FALLING",
            // 資料型態
            "boolean", "byte", "int", "long", "float", "double",
            "char", "word", "size_t",
            "uint8_t", "uint16_t", "uint32_t", "int8_t", "int16_t", "int32_t",
            // 預處理器
            "NULL"
          ]
        };
      return {
        name: "Arduino",
        aliases: ["arduino", "cpp"],
        keywords: s,
        contains: [
          e.C_LINE_COMMENT_MODE,
          e.C_BLOCK_COMMENT_MODE,
          e.C_NUMBER_MODE,
          e.QUOTE_STRING_MODE
        ]
      };
    };
  })();
  hljs.registerLanguage("arduino", e);
})();